// Scan for any blocks ahead to continue the parkour course
let blocks = bot.findBlocks({
    matching: block => block && block.name && !['air', 'water', 'sand', 'short_dry_grass', 'tall_dry_grass', 'seagrass', 'kelp', 'kelp_plant'].includes(block.name),
    maxDistance: 32,
    count: 40
});

let p = bot.entity.position;
// Filter out blocks we are already standing on or too close to, and sort by distance and height
let targets = blocks.filter(b => b.distanceTo(p) > 2);
targets.sort((a, b) => p.distanceTo(a) - p.distanceTo(b));

if (targets.length > 0) {
    let target = targets[0];
    bot.chat(`Jumping to ${target.name} at ${target.x}, ${target.y}, ${target.z}`);
    await skills.goToPosition(bot, target.x, target.y, target.z);
} else {
    bot.chat("No parkour blocks found nearby, moving forward to explore.");
    await skills.goToPosition(bot, p.x, p.y, p.z - 4);
}```
